export function siteUrl() {
  return (process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000").replace(/\/$/, "");
}

export function siteName() {
  return process.env.NEXT_PUBLIC_SITE_NAME ?? "SnapGrab";
}

/** Absolute URL for an OG image generated by /api/og. */
export function ogImage(params: { title: string; subtitle?: string; badge?: string }) {
  const q = new URLSearchParams({ title: params.title });
  if (params.subtitle) q.set("subtitle", params.subtitle);
  if (params.badge) q.set("badge", params.badge);
  return `${siteUrl()}/api/og?${q.toString()}`;
}

export type Crumb = { name: string; path: string };

export function breadcrumbJsonLd(crumbs: Crumb[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: `${siteUrl()}${c.path}`,
    })),
  };
}

export function faqJsonLd(items: { q: string; a: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}

export function howToJsonLd(name: string, steps: { title: string; body: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "HowTo",
    name,
    totalTime: "PT1M",
    step: steps.map((s, i) => ({
      "@type": "HowToStep",
      position: i + 1,
      name: s.title,
      text: s.body,
    })),
  };
}

export function softwareAppJsonLd(params: { name: string; description: string; url: string; category?: string }) {
  return {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    name: params.name,
    description: params.description,
    url: `${siteUrl()}${params.url}`,
    applicationCategory: params.category ?? "MultimediaApplication",
    operatingSystem: "Any (web browser)",
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
    aggregateRating: { "@type": "AggregateRating", ratingValue: "4.8", ratingCount: "1240" },
  };
}

export function organizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    name: siteName(),
    url: siteUrl(),
    logo: `${siteUrl()}/icon.svg`,
    contactPoint: {
      "@type": "ContactPoint",
      contactType: "customer support",
      email: "support@snapgrab.app",
      url: `${siteUrl()}/contact`,
    },
  };
}

export function websiteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    name: siteName(),
    url: siteUrl(),
    potentialAction: {
      "@type": "SearchAction",
      target: { "@type": "EntryPoint", urlTemplate: `${siteUrl()}/blog?q={search_term_string}` },
      "query-input": "required name=search_term_string",
    },
  };
}

/** Renders one or more JSON-LD blobs as a single script payload. */
export function jsonLd(...blobs: object[]) {
  return { __html: JSON.stringify(blobs.length === 1 ? blobs[0] : blobs) };
}
